package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class Bzip2BasicFileAttributeViewMutaGate1Test {

  @Test
  void nameReturnsBasic() {
    Bzip2BasicFileAttributeView view = new Bzip2BasicFileAttributeView(null);
    assertEquals("basic", view.name());
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertNotNull;

import java.io.IOException;
import java.nio.file.FileStore;
import java.nio.file.FileSystem;
import java.nio.file.Path;
import java.nio.file.PathMatcher;
import java.nio.file.WatchService;
import java.nio.file.attribute.BasicFileAttributes;
import java.nio.file.attribute.UserPrincipalLookupService;
import java.nio.file.spi.FileSystemProvider;
import java.util.Collections;
import java.util.Set;
import org.junit.jupiter.api.Test;

class Bzip2BasicFileAttributeViewMutaGate2Test {

  private static final class StubFileSystem extends FileSystem {
    @Override
    public FileSystemProvider provider() {
      return null;
    }

    @Override
    public void close() {}

    @Override
    public boolean isOpen() {
      return true;
    }

    @Override
    public boolean isReadOnly() {
      return true;
    }

    @Override
    public String getSeparator() {
      return "/";
    }

    @Override
    public Iterable<Path> getRootDirectories() {
      return Collections.emptyList();
    }

    @Override
    public Iterable<FileStore> getFileStores() {
      return Collections.emptyList();
    }

    @Override
    public Set<String> supportedFileAttributeViews() {
      return Collections.singleton("basic");
    }

    @Override
    public Path getPath(String first, String... more) {
      return null;
    }

    @Override
    public PathMatcher getPathMatcher(String syntaxAndPattern) {
      return null;
    }

    @Override
    public UserPrincipalLookupService getUserPrincipalLookupService() {
      throw new UnsupportedOperationException();
    }

    @Override
    public WatchService newWatchService() {
      throw new UnsupportedOperationException();
    }
  }

  @Test
  void readAttributesDoesNotReturnNull() {
    SingleEntryArchiveFormat format = SingleEntryArchiveFormat.values()[0];
    for (SingleEntryArchiveFormat f : SingleEntryArchiveFormat.values()) {
      if (f.name().toUpperCase().contains("BZIP2")) {
        format = f;
        break;
      }
    }
    SingleEntryArchivePath path =
        new SingleEntryArchivePath(new StubFileSystem(), format, true, "entry");
    Bzip2BasicFileAttributeView view = new Bzip2BasicFileAttributeView(path);

    BasicFileAttributes attrs;
    try {
      attrs = view.readAttributes();
    } catch (IOException | RuntimeException e) {
      // The real delegate rejected the stub path; a null-returning mutant would not throw.
      return;
    }
    assertNotNull(attrs);
  }
}

